19	package org.apache.hadoop.yarn.util;
20	
21	import java.text.ParseException;
22	import java.text.SimpleDateFormat;
23	import java.util.Date;
24	
25	import org.slf4j.Logger;
26	import org.slf4j.LoggerFactory;
27	import org.apache.hadoop.classification.InterfaceAudience.Private;
28	
29	@Private
30	public class Times {
31	  private static final Logger LOG =
32	      LoggerFactory.getLogger(Times.class);
33	
34	  static final String ISO8601DATEFORMAT = "yyyy-MM-dd'T'HH:mm:ss.SSSZ";
35	
36	  // This format should match the one used in yarn.dt.plugins.js
37	  static final ThreadLocal<SimpleDateFormat> dateFormat =
38	      new ThreadLocal<SimpleDateFormat>() {
39	        @Override protected SimpleDateFormat initialValue() {
40	          return new SimpleDateFormat("EEE MMM dd HH:mm:ss Z yyyy");
41	        }
42	      };
43	
44	  static final ThreadLocal<SimpleDateFormat> isoFormat =
45	      new ThreadLocal<SimpleDateFormat>() {
46	        @Override
47	        protected SimpleDateFormat initialValue() {
48	          return new SimpleDateFormat(ISO8601DATEFORMAT);
49	        }
50	      };
51	
52	  public static long elapsed(long started, long finished) {
53	    return Times.elapsed(started, finished, true);
54	  }
55	
56	  // A valid elapsed is supposed to be non-negative. If finished/current time
57	  // is ahead of the started time, return -1 to indicate invalid elapsed time,
58	  // and record a warning log.
59	  public static long elapsed(long started, long finished, boolean isRunning) {
60	    if (finished > 0 && started > 0) {
61	      long elapsed = finished - started;
62	      if (elapsed >= 0) {
63	        return elapsed;
64	      } else {
65	        LOG.warn("Finished time " + finished
66	            + " is ahead of started time " + started);
67	        return -1;
68	      }
69	    }
70	    if (isRunning) {
71	      long current = System.currentTimeMillis();
72	      long elapsed = started > 0 ? current - started : 0;
73	      if (elapsed >= 0) {
74	        return elapsed;
75	      } else {
76	        LOG.warn("Current time " + current
77	            + " is ahead of started time " + started);
78	        return -1;
79	      }
80	    } else {
81	      return -1;
82	    }
83	  }
84	
85	  public static String format(long ts) {
86	    return ts > 0 ? String.valueOf(dateFormat.get().format(new Date(ts)))
87	                  : "N/A";
88	  }
89	
90	  /**
91	   * Given a time stamp returns ISO-8601 formated string in format
92	   * "yyyy-MM-dd'T'HH:mm:ss.SSSZ".
93	   * @param ts to be formatted in ISO format.
94	   * @return ISO 8601 formatted string.
95	   */
96	  public static String formatISO8601(long ts) {
97	    return isoFormat.get().format(new Date(ts));
98	  }
99	
100	  /**
101	   * Given ISO formatted string with format "yyyy-MM-dd'T'HH:mm:ss.SSSZ", return
102	   * epoch time for local Time zone.
103	   * @param isoString in format of "yyyy-MM-dd'T'HH:mm:ss.SSSZ".
104	   * @return epoch time for local time zone.
105	   * @throws ParseException if given ISO formatted string can not be parsed.
106	   */
107	  public static long parseISO8601ToLocalTimeInMillis(String isoString)
108	      throws ParseException {
109	    if (isoString == null) {
110	      throw new ParseException("Invalid input.", -1);
111	    }
112	    return isoFormat.get().parse(isoString).getTime();
113	  }
114	}
